std::uint64_t rc12_cpu(HANDLE process){FILETIME created{},exited{},kernel{},user{};check(GetProcessTimes(process,&created,&exited,&kernel,&user)!=FALSE,"read process CPU counters");ULARGE_INTEGER k{},u{};k.LowPart=kernel.dwLowDateTime;k.HighPart=kernel.dwHighDateTime;u.LowPart=user.dwLowDateTime;u.HighPart=user.dwHighDateTime;return k.QuadPart+u.QuadPart;}
DWORD rc12_runtime(DWORD parent){win32::installation::Handle snapshot(CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0));check(snapshot.get()!=INVALID_HANDLE_VALUE,"process snapshot");PROCESSENTRY32W p{sizeof(p)};if(Process32FirstW(snapshot.get(),&p))do{if(p.th32ParentProcessID==parent&&std::wstring(p.szExeFile)==L"SFXRuntime.exe")return p.th32ProcessID;}while(Process32NextW(snapshot.get(),&p));return 0;}
int main(int argc,char** argv){Product panel;std::optional<app::FtnConfiguration> original;const auto root=win32::installation::canonical_root(L"C:/Program Files/SFX-OwnerFixes-Test-20261031-r3");const auto owner=win32::current_process_user_sid_string();const auto save=[&](const app::FtnConfiguration& value){GUID id{};check(SUCCEEDED(CoCreateGuid(&id)),"fresh synthetic settings operation");app::FtnTransferToken token{};memcpy(token.data(),&id,token.size());check(bool(win32::offline_change_ftn_configuration(root,owner,token,value)),"normal isolated FTN settings transaction");};try{
    check(argc==2,"fresh idle output required");const auto out=std::filesystem::absolute(argv[1]);check(!std::filesystem::exists(out),"preserve idle evidence");std::filesystem::create_directories(out);check(!win32::installation::elevated(),"ordinary user idle measurement");win32::installation::verify_runtime_installation(root,owner);
    const auto before=win32::offline_ftn_configuration(root,owner);check(before&&before.value&&before.value->networks.size()==1&&before.value->links.size()==1&&before.value->networks[0].name=="Owner fix regression"&&!before.value->networks[0].enabled&&!before.value->links[0].enabled,"exact stopped synthetic peer fixture only");original=*before.value;
    auto active=*original;active.networks[0].enabled=true;active.settings.listener_enabled=true;active.settings.bind_address="127.0.0.1";active.settings.tls_listener_enabled=false;save(active);
    panel=launch(root/L"Bin/SFXControlPanel.exe",L"");panel.window=wait_window(panel.pid,kWindowClass);const auto deadline=GetTickCount64()+30000;while(!visible_text_contains(panel.window,L"READY")&&GetTickCount64()<deadline)Sleep(20);check(visible_text_contains(panel.window,L"READY"),"synthetic Runtime ready");const auto receipt=win32::installation::read_receipt(root,owner);const auto pid=rc12_runtime(panel.pid);check(pid!=0,"identify owned Runtime child");win32::installation::verify_installed_program_process(receipt,pid,win32::installation::runtime_program_index);win32::installation::Handle runtime(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,pid));check(bool(runtime),"pin owned Runtime process");
    SYSTEM_INFO system{};GetSystemInfo(&system);std::ofstream report(out/L"cpu.tsv");report<<"state\twall_ms\tlogical_processors\truntime_cpu_ms\tpanel_cpu_ms\truntime_percent\tpanel_percent\n";
    const auto tab=GetDlgItem(panel.window,IDC_MAIN_TAB);SendMessageW(tab,WM_KEYDOWN,VK_HOME,0);SendMessageW(tab,WM_KEYDOWN,VK_RIGHT,0);check(TabCtrl_GetCurSel(tab)==1,"BinkP page selected for idle sample");
    for(const bool minimized:{false,true}){ShowWindow(panel.window,minimized?SW_MINIMIZE:SW_RESTORE);Sleep(2000);const auto start=GetTickCount64(),runtime_before=rc12_cpu(runtime.get()),panel_before=rc12_cpu(panel.process.get());Sleep(15000);const auto wall=GetTickCount64()-start;const auto runtime_ms=(rc12_cpu(runtime.get())-runtime_before)/10000.0,panel_ms=(rc12_cpu(panel.process.get())-panel_before)/10000.0;report<<(minimized?"minimized":"visible")<<'\t'<<wall<<'\t'<<system.dwNumberOfProcessors<<'\t'<<runtime_ms<<'\t'<<panel_ms<<'\t'<<runtime_ms*100/(wall*system.dwNumberOfProcessors)<<'\t'<<panel_ms*100/(wall*system.dwNumberOfProcessors)<<'\n';report.flush();check(WaitForSingleObject(runtime.get(),0)==WAIT_TIMEOUT,"Runtime remains alive during idle sample");}
    ShowWindow(panel.window,SW_RESTORE);Sleep(1000);render_foreign_png(panel.window,out/L"idle-panel.png");close_panel(panel);auto current=win32::offline_ftn_configuration(root,owner);check(current&&current.value,"saved test settings readable after measurement");original->revision=current.value->revision;save(*original);current=win32::offline_ftn_configuration(root,owner);original->revision=current.value->revision;check(app::encode_ftn_configuration(*original)==app::encode_ftn_configuration(*current.value),"exact original FTN business settings restored");std::cout<<"PASS RC12 CPU measurement "<<checks<<" checks; enabled loopback listener/disabled outbound peer; normalized counters in cpu.tsv\n";return 0;
}catch(const std::exception& error){try{close_panel(panel);if(original){const auto current=win32::offline_ftn_configuration(root,owner);if(current&&current.value){original->revision=current.value->revision;save(*original);}}}catch(...){}std::cerr<<"FAIL RC12 idle "<<checks<<": "<<error.what()<<'\n';return 1;}}
